import copy
import itertools
import unittest
from planner import order_jobs

class PlannerTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(order_jobs({}), [])
    def test_dependency_direction(self):
        self.assertEqual(order_jobs({'a':['z'],'z':[]}), ['z','a'])
    def test_dynamic_tie_break(self):
        self.assertEqual(order_jobs({'z':[],'a':['b'],'b':[]}), ['b','a','z'])
    def test_diamond(self):
        self.assertEqual(order_jobs({'end':['left','right'],'left':['start'],'right':['start'],'start':[]}), ['start','left','right','end'])
    def test_duplicate_edges(self):
        self.assertEqual(order_jobs({'a':['b','b'],'b':[]}), ['b','a'])
    def test_cycles(self):
        for jobs in [{'a':['a']},{'a':['b'],'b':['a']},{'a':[],'b':['c'],'c':['b']}]:
            with self.subTest(jobs=jobs):
                with self.assertRaises(ValueError): order_jobs(jobs)
    def test_unknown(self):
        with self.assertRaises(ValueError): order_jobs({'a':['missing']})
    def test_invalid_shapes(self):
        for jobs in [None, [], {'':[]}, {1:[]}, {'a':'a'}, {'a':None}, {'a':[1]}, {'a':[[]]}]:
            with self.subTest(jobs=jobs):
                with self.assertRaises(ValueError): order_jobs(jobs)
    def test_no_mutation(self):
        jobs={'c':['b','a','b'],'b':[],'a':[]}
        before=copy.deepcopy(jobs)
        self.assertEqual(order_jobs(jobs),['a','b','c'])
        self.assertEqual(jobs,before)
    def test_all_three_node_digraphs(self):
        nodes=['a','b','c']
        possible=list(itertools.permutations(nodes,2))
        for mask in range(1<<len(possible)):
            jobs={n:[] for n in nodes}
            for index,(src,dst) in enumerate(possible):
                if mask & (1<<index): jobs[dst].append(src)
            valid=[]
            for order in itertools.permutations(nodes):
                positions={node:i for i,node in enumerate(order)}
                if all(positions[d]<positions[n] for n in nodes for d in jobs[n]): valid.append(order)
            with self.subTest(mask=mask):
                if valid: self.assertEqual(order_jobs(jobs),list(min(valid)))
                else:
                    with self.assertRaises(ValueError): order_jobs(jobs)

if __name__=='__main__': unittest.main()

