import copy
import random
import unittest
from ledger import move_money

def event(ident='x',src='a',dst='b',cents=10):
    return {'id':ident,'src':src,'dst':dst,'cents':cents}

class LedgerTests(unittest.TestCase):
    def test_empty_and_independent_result(self):
        balances={'a':0,'b':100}
        result=move_money(balances,[])
        self.assertEqual(result,balances)
        self.assertIsNot(result,balances)
        self.assertEqual(move_money({},[]),{})
    def test_transfer(self):
        self.assertEqual(move_money({'a':100,'b':20},[event(cents=35)]),{'a':65,'b':55})
    def test_sequential(self):
        self.assertEqual(move_money({'a':100,'b':0,'c':0},[event(cents=80),event('y','b','c',75)]),{'a':20,'b':5,'c':75})
    def test_duplicate_is_idempotent_before_funds_check(self):
        e=event(cents=70)
        self.assertEqual(move_money({'a':100,'b':0},[e,dict(reversed(list(e.items())))]),{'a':30,'b':70})
    def test_conflicting_duplicate(self):
        with self.assertRaises(ValueError): move_money({'a':100,'b':0},[event(),event(cents=20)])
    def test_self_transfer(self):
        self.assertEqual(move_money({'a':30},[event('x','a','a',30)]),{'a':30})
        with self.assertRaises(ValueError): move_money({'a':30},[event('x','a','a',31)])
    def test_insufficient_and_unknown(self):
        for e in [event(cents=101),event(src='missing'),event(dst='missing')]:
            with self.subTest(e=e):
                with self.assertRaises(ValueError): move_money({'a':100,'b':0},[e])
    def test_invalid_initial_balances(self):
        for b in [None,[],{'a':-1},{'a':True},{'a':1.2},{'':0},{1:0}]:
            with self.subTest(b=b):
                with self.assertRaises(ValueError): move_money(b,[])
    def test_invalid_events(self):
        cases=[None,{},[None],[{}],[dict(event(),extra=1)]]
        cases += [[event(cents=x)] for x in [0,-1,True,1.5,'1',None]]
        cases += [[event(ident=x)] for x in ['',1,None]]
        for field in ['src','dst']:
            for value in ['',1,None]:
                e=event();e[field]=value;cases.append([e])
        for events in cases:
            with self.subTest(events=events):
                with self.assertRaises(ValueError): move_money({'a':100,'b':0},events)
    def test_no_mutation_on_success(self):
        balances={'a':100,'b':0};events=[event()]
        before=copy.deepcopy((balances,events))
        result=move_money(balances,events)
        self.assertEqual((balances,events),before)
        result['a']=0
        self.assertEqual(balances['a'],100)
    def test_no_partial_mutation_on_failure(self):
        balances={'a':100,'b':0};events=[event(cents=30),event('y',cents=100)]
        before=copy.deepcopy((balances,events))
        with self.assertRaises(ValueError): move_money(balances,events)
        self.assertEqual((balances,events),before)
    def test_generated_valid_sequences(self):
        rng=random.Random(7919)
        for case in range(30):
            initial={n:100 for n in 'abcd'};expected=dict(initial);events=[]
            for i in range(20):
                src=rng.choice([n for n in expected if expected[n]>0]);dst=rng.choice(list(expected));amount=rng.randint(1,expected[src])
                expected[src]-=amount;expected[dst]+=amount
                e=event(str(i),src,dst,amount);events.append(e)
                if i%3==0:events.append(dict(e))
            with self.subTest(case=case):
                self.assertEqual(move_money(initial,events),expected)
                self.assertEqual(sum(move_money(initial,events).values()),400)

if __name__=='__main__': unittest.main()
